"""Derive scoped timing summaries from validated raw observations, never golden times."""
from collections import defaultdict
from pathlib import Path
import argparse,math,statistics,json
from common import ROOT,read_json,dump,sha
from check_completion_followthrough import validate
def percentile(values,p):return sorted(values)[max(0,math.ceil(len(values)*p)-1)]
def main():
 p=argparse.ArgumentParser();p.add_argument('--report',required=True);a=p.parse_args();report=read_json(ROOT/a.report);assert not validate(report);groups=defaultdict(list)
 for command in report['commands']:
  name=Path(command['argv'][0]).name
  if name not in ('gcc-workload','clang-workload'):continue
  row=json.loads(command['stdout']);groups[(name.split('-')[0],row['backend'],row['depth'],row['length'],row['cache_request'])].append(row)
 rows=[]
 for key,values in sorted(groups.items()):
  cc,backend,depth,length,cache=key;latency=[n for v in values for n in v['latency_ns']];steady=[n for v in values for n in v['latency_ns'][depth:]];assert len(values)==3 and len(latency)==192
  rows.append(dict(compiler=cc,backend=backend,depth=depth,length=length,cache=cache,trials=3,request_samples=192,whole_ns=[v['whole_ns'] for v in values],whole_median_ns=statistics.median(v['whole_ns'] for v in values),cpu_median_ns=statistics.median(v['cpu_ns'] for v in values),latency_p50_ns=percentile(latency,.5),latency_p99_ns=percentile(latency,.99),steady_p50_ns=percentile(steady,.5),steady_p99_ns=percentile(steady,.99),allocated_payload_bytes=values[0]['allocated_payload_bytes'],registered_payload_bytes=values[0]['registered_payload_bytes'],pin_interval_ns=[v['pin_interval_ns'] for v in values],ring_mapping_bytes=values[0]['ring_mapping_bytes'],maximum_sent_unconsumed_bytes=max(v['maximum_sent_unconsumed_bytes'] for v in values)))
 out=ROOT/'reviews/v5/expansion/legacy_completion_io/workload_summary.json';dump(out,dict(passed=True,input_sha256={a.report:sha(ROOT/a.report),'tools/summarize_completion_workloads.py':sha(Path(__file__))},rows=rows,method='Nearest-rank empirical quantiles;192 correlated request samples per cell,3 whole-workload trials; steady excludes exactly the declared first batch, while whole timings retain it.',limits=['These distributions are scoped guest observations, not confidence bounds or worst-case latency.','Process CPU excludes io_uring kernel-worker CPU; user mappings are lengths, not page-rounded resident memory.','Cache labels are admission mincore snapshots after owned-file preparation, not physical storage cache state.','The author prediction disclosed four pilot cells and is not independent learner evidence.']))
 lines=['# Completion-I/O current author validation','','The source-bound campaign passed298 commands and six ordinary/changed criterion observations. It runs the actual retained T62 raw ring with ordinary and fixed-buffer reads, cancellation and synchronous unregistration. No liburing fallback or host-policy change is used.','',f'Campaign: `{a.report}`; SHA256 `{sha(ROOT/a.report)}`.','', 'Verification includes six compiler/instrumentation profiles,720 independent event permutations/4320 transitions per profile, actual full-socket copy/sendfile experiments, nine compiled unsolved/semantic rejection paths and an independently rejected wrong-offset implementation. The separate evidence guard and actual learner export retain their own receipts.','', 'A multi-source Clang stack report overwrote earlier translation-unit output. Attempt01 is retained; the current campaign separately compiles and retains each required workload stack report. The original research-folder collision and restoration are recorded in `research/v5/expansion/followthrough/completion_namespace_correction.json`; current I/O sources are isolated under `legacy_completion_io`.','', 'The table reports medians/empirical upper quantiles, not portable golden timing. Whole measurements include setup, the declared first-batch10ms hold, byte verification and cleanup. Steady columns exclude precisely the first batch and do not replace the whole result. Raw latency arrays and all192 matrix commands remain in the campaign.','', '| Compiler/backend | Depth / bytes / cache | Whole median µs | CPU median µs | Request p50 / p99 µs | Steady p50 / p99 µs |','|---|---|---:|---:|---:|---:|']
 for r in rows:lines.append(f"| {r['compiler']}/{r['backend']} | {r['depth']} / {r['length']} / {r['cache']} | {r['whole_median_ns']/1000:.3f} | {r['cpu_median_ns']/1000:.3f} | {r['latency_p50_ns']/1000:.3f} / {r['latency_p99_ns']/1000:.3f} | {r['steady_p50_ns']/1000:.3f} / {r['steady_p99_ns']/1000:.3f} |")
 lines += ['', 'All64 distinct configuration cells contain3 trials and192 request samples. Native cancellation records the observed two-CQE order and latency; the event-set model separately covers both orders. Stalled synchronous sends measure stop-admission-to-drained time. No scheduler-independent bound, hidden kernel-copy count, physical device result, external review or learner/delayed performance is inferred.']
 (out.parent/'CURRENT_VALIDATION.md').write_text('\n'.join(lines)+'\n',encoding='utf8',newline='\n');print(dict(cells=len(rows),trials=sum(r['trials'] for r in rows),passed=True))
if __name__=='__main__':main()
